:root{--sans:-apple-system, BlinkMacSystemFont, "Segoe UI Variable Text", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;--mono:ui-monospace, "SF Mono", "Cascadia Mono", "JetBrains Mono", Menlo, Consolas, "Liberation Mono", monospace;--fs-label:12px;--fs-small:13px;--fs-card:14px;--fs-body:16px;--fs-lede:18px;--fs-h3:17px;--fs-h2:22px;--fs-h1:clamp(28px, 1.1rem + 2vw, 36px);--fs-display:clamp(36px, 1.4rem + 3.2vw, 52px);--fs-kpi:26px;--s-1:4px;--s-2:8px;--s-3:12px;--s-4:16px;--s-5:24px;--s-6:32px;--s-7:48px;--s-8:64px;--s-9:96px;--r-lg:12px;--r-md:8px;--r-sm:6px;--r-pill:999px;--ease:cubic-bezier(.2,.7,.2,1);--dur:140ms;--bar-h:56px;--measure:70ch;--wrap:1200px}
