.bslib-page-sidebar>.navbar,.bslib-page-title{background:var(--surface);color:var(--ink);border-bottom:1px solid var(--line-2)}
.bslib-sidebar-layout{--bslib-sidebar-bg:var(--surface);--_sidebar-bg:var(--surface);--bslib-sidebar-fg:var(--text);--bslib-sidebar-border:1px solid var(--line-2);
 --bslib-sidebar-toggle-bg:var(--surface-3);--bslib-collapse-toggle-color:var(--muted)}
.bslib-sidebar-layout>.collapse-toggle{color:var(--muted)}
.bslib-sidebar-layout>.collapse-toggle:hover{color:var(--ink)}
.card,.bslib-card{--bs-card-bg:var(--surface);--bs-card-color:var(--text);--bs-card-border-color:var(--line-2);--bs-card-cap-bg:var(--surface-2);
 --bs-card-cap-color:var(--ink);--bs-card-border-radius:var(--r-lg);--bs-card-inner-border-radius:calc(var(--r-lg) - 1px);box-shadow:var(--shadow-1)}
.card>.card-header{font-weight:650;border-bottom-color:var(--line)}
.card>.card-footer{background:transparent;border-top-color:var(--line);color:var(--muted)}
.nav{--bs-nav-link-color:var(--muted);--bs-nav-link-hover-color:var(--ink)}
.nav-tabs{--bs-nav-tabs-border-color:var(--line-2);--bs-nav-tabs-link-hover-border-color:var(--line-2) var(--line-2) var(--line-2);
