.selectize-input input{color:var(--ink)}
.selectize-control.single .selectize-input:after{border-top-color:var(--muted)}
.selectize-dropdown,.selectize-dropdown.form-control{background:var(--surface);color:var(--text);border-color:var(--line-2)}
.selectize-dropdown .active:not(.selected){background:var(--accent-soft);color:var(--ink)}
.selectize-dropdown .selected{background:var(--accent);color:var(--on-accent)}
.form-label,.control-label{color:var(--ink)}
.form-check-input{background-color:var(--surface);border-color:var(--control)}
.form-check-input:checked{background-color:var(--accent);border-color:var(--accent)}
.form-check-input:checked[type=checkbox]{--bs-form-check-bg-image:var(--bp-check)}
.form-check-input:checked[type=radio]{--bs-form-check-bg-image:var(--bp-radio)}
.form-check-input:focus{border-color:var(--accent);box-shadow:0 0 0 .2rem var(--accent-ring)}
.table{--bs-table-bg:transparent;--bs-table-color:var(--text);--bs-table-border-color:var(--line);
 --bs-table-striped-bg:color-mix(in srgb,var(--ink) 3.5%,transparent);--bs-table-striped-color:var(--text);
 --bs-table-hover-bg:var(--accent-soft);--bs-table-hover-color:var(--ink);--bs-table-active-bg:var(--accent-soft);--bs-table-active-color:var(--ink)}
.table thead th,table.dataTable thead th{color:var(--muted);border-bottom-color:var(--line-2)}
html .table.dataTable,html table.dataTable{--dt-row-selected:var(--bp-sel-rgb);--dt-row-selected-text:var(--bp-sel-text-rgb);--dt-row-selected-link:var(--bp-sel-link-rgb)}
html table.dataTable>tbody>tr.selected>td:first-child{box-shadow:inset 3px 0 0 var(--accent),inset 0 0 0 9999px rgb(var(--dt-row-selected))}
div.dataTables_wrapper div.dataTables_info,div.dataTables_wrapper div.dataTables_length label,div.dataTables_wrapper div.dataTables_filter label{color:var(--muted)}
.pagination{--bs-pagination-color:var(--accent-ink);--bs-pagination-bg:var(--surface);--bs-pagination-border-color:var(--line-2);
 --bs-pagination-hover-color:var(--ink);--bs-pagination-hover-bg:var(--surface-3);--bs-pagination-hover-border-color:var(--line-2);
 --bs-pagination-focus-color:var(--ink);--bs-pagination-focus-bg:var(--surface-3);--bs-pagination-focus-box-shadow:0 0 0 .2rem var(--accent-ring);
 --bs-pagination-active-color:var(--on-accent);--bs-pagination-active-bg:var(--accent);--bs-pagination-active-border-color:var(--accent);
 --bs-pagination-disabled-color:var(--faint);--bs-pagination-disabled-bg:var(--surface);--bs-pagination-disabled-border-color:var(--line)}
.accordion{--bs-accordion-color:var(--text);--bs-accordion-bg:var(--surface);--bs-accordion-border-color:var(--line-2);--bs-accordion-btn-color:var(--ink);
 --bs-accordion-btn-bg:var(--surface);--bs-accordion-active-color:var(--ink);--bs-accordion-active-bg:var(--surface-2);
 --bs-accordion-btn-focus-box-shadow:0 0 0 .2rem var(--accent-ring);--bs-accordion-border-radius:var(--r-lg);--bs-accordion-inner-border-radius:calc(var(--r-lg) - 1px)}
.accordion{box-shadow:var(--shadow-1);border-radius:var(--r-lg)}
.bslib-value-box{--bs-card-bg:var(--surface)}
.bslib-value-box .value-box-title{color:var(--muted)}
.bslib-value-box .value-box-value{color:var(--ink)}
#shiny-notification-panel .shiny-notification{background:var(--surface);color:var(--text);border:1px solid var(--line-2);border-left:4px solid var(--accent);
 border-radius:var(--r-md);opacity:1;box-shadow:var(--shadow-2)}
.shiny-notification-close{color:var(--muted)}
.irs--shiny .irs-bar{background:var(--accent);border-color:var(--accent)}
.irs--shiny .irs-line{background:var(--surface-3);border-color:var(--line-2)}
.irs--shiny .irs-handle{background:var(--surface);border-color:var(--accent)}
.irs--shiny .irs-handle.state_hover,.irs--shiny .irs-handle:hover{background:var(--surface-3)}
.irs--shiny .irs-single,.irs--shiny .irs-from,.irs--shiny .irs-to{background:var(--accent);color:var(--on-accent)}
.irs--shiny .irs-single:before,.irs--shiny .irs-from:before,.irs--shiny .irs-to:before{border-top-color:var(--accent)}
.irs--shiny .irs-min,.irs--shiny .irs-max{background:var(--surface-3);color:var(--muted)}
.irs--shiny .irs-grid-text{color:var(--muted)}
.irs--shiny .irs-grid-pol{background:var(--line-2)}
.bp-label{font:600 var(--fs-label)/1.3 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.bp-chip{display:inline-flex;align-items:center;gap:6px;padding:2px 9px;border:1px solid var(--tone-neutral-line);border-radius:var(--r-sm);
 background:var(--tone-neutral-bg);color:var(--tone-neutral-fg);font:500 12px/1.35 var(--mono);white-space:nowrap;vertical-align:middle}
.bp-chip::before{content:"";flex:none;width:6px;height:6px;background:currentColor}
.bp-chip.synthetic{border-color:var(--tone-amber-line);background:var(--tone-amber-bg);color:var(--tone-amber-fg)}
.bp-theme-toggle{display:inline-flex;align-items:center;justify-content:center;flex:none;width:36px;height:36px;padding:0;border:1px solid var(--control);
 border-radius:var(--r-sm);background:transparent;color:var(--text);cursor:pointer}
.bp-theme-toggle:hover{color:var(--ink);background:var(--surface-3)}
.bp-theme-toggle svg{width:18px;height:18px;display:block}
html:not([data-bs-theme=light]) .bp-theme-toggle .i-sun,html[data-bs-theme=light] .bp-theme-toggle .i-moon{display:none}
html.bp-embedded .bp-theme-toggle{display:none}
.bp-sr{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0}
@media (pointer:coarse){.bp-theme-toggle{width:44px;height:44px}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}})---"

bp_head_js <- r"---((function (d) {
  var r = d.documentElement, K = "bp-theme", mq = window.matchMedia ? window.matchMedia("(prefers-color-scheme: light)") : null;
  function saved() { try { var t = localStorage.getItem(K); return t === "light" || t === "dark" ? t : null; } catch (e) { return null; } }
  function want() { return saved() || (mq && mq.matches ? "light" : "dark"); }
  function cur() { return r.getAttribute("data-bs-theme") === "light" ? "light" : "dark"; }
  function paint() {
    var dark = cur() === "dark";
    [].forEach.call(d.querySelectorAll(".bp-theme-toggle"), function (b) {
      b.setAttribute("aria-pressed", dark ? "true" : "false");
      b.title = dark ? "Switch to light theme" : "Switch to dark theme";
      var s = b.querySelector(".bp-sr"); if (s) s.textContent = dark ? "Dark theme" : "Light theme";
    });
  }
  function set(t) { if (t !== "light" && t !== "dark") t = want(); if (r.getAttribute("data-bs-theme") !== t) r.setAttribute("data-bs-theme", t); }
  set(want());
  try { if (window.self !== window.top) r.classList.add("bp-embedded"); } catch (e) { r.classList.add("bp-embedded"); }
  window.addEventListener("storage", function (e) { if (e.key === K || e.key === null) set(want()); });
  if (mq && mq.addEventListener) mq.addEventListener("change", function () { if (!saved()) set(want()); });
  window.bpTheme = { get: cur, want: want, set: set,
    toggle: function () { var t = cur() === "dark" ? "light" : "dark"; try { localStorage.setItem(K, t); } catch (e) {} set(t); } };
  d.addEventListener("click", function (e) {
    var b = e.target.closest ? e.target.closest(".bp-theme-toggle") : null;
    if (b) { e.preventDefault(); window.bpTheme.toggle(); }
  });
  new MutationObserver(function () {
    paint();
    if (window.jQuery) window.jQuery(".bp-theme-input").trigger("bp-theme");
  }).observe(r, { attributes: true, attributeFilter: ["data-bs-theme"] });
  d.addEventListener("DOMContentLoaded", paint);
  function bind() {
    if (bind.done || !window.Shiny || !window.Shiny.InputBinding || !window.jQuery) return;
    bind.done = true;
    var $ = window.jQuery, B = new window.Shiny.InputBinding();
    $.extend(B, {
      find: function (scope) { return $(scope).find(".bp-theme-input"); },
      getValue: function () { return cur(); },
      subscribe: function (el, cb) { $(el).on("bp-theme.bpTheme", function () { cb(false); }); },
      unsubscribe: function (el) { $(el).off(".bpTheme"); }
    });
    window.Shiny.inputBindings.register(B, "bp.theme");
  }
  bind();
  d.addEventListener("DOMContentLoaded", bind);
})(document);)---"

bp_theme <- function(...) bslib::bs_theme(version = 5, ...)

bp_theme_head <- function() {
  htmltools::tagList(
    htmltools::tags$head(
      htmltools::tags$meta(name = "color-scheme", content = "dark light"),
      htmltools::tags$script(htmltools::HTML(bp_head_js)),
      htmltools::tags$style(id = "bp-theme-css", htmltools::HTML(bp_css))),
    htmltools::span(id = "bp_theme", class = "bp-theme-input", hidden = NA))
}

bp_theme_toggle <- function() {
  htmltools::tags$button(
    type = "button", class = "bp-theme-toggle", title = "Switch to light theme", `aria-pressed` = "true",
    htmltools::HTML('<svg class="i-moon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="M20.6 14.2A8.5 8.5 0 0 1 9.8 3.4a8.5 8.5 0 1 0 10.8 10.8z"/></svg><svg class="i-sun" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="4.2" fill="currentColor"/><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M5.3 18.7l1.6-1.6M17.1 6.9l1.6-1.6"/></svg>'), htmltools::span(class = "bp-sr", "Dark theme"))
}

bp_palette <- function(mode = "dark") {
  m <- if (identical(mode, "light")) "light" else "dark"
  c(as.list(bp_tokens[[m]]), list(tone = bp_tones[[m]], mode = m))
}

# Neutral chart ink for ggplot2; series colors come from bp_tones, chosen by each app.
bp_ggplot_theme <- function(mode = c("dark", "light"), base_size = 12) {
  k <- bp_tokens[[match.arg(mode)]]
  ggplot2::theme_minimal(base_size = base_size) + ggplot2::theme(
    plot.background = ggplot2::element_rect(fill = k[["surface"]], color = NA),
    panel.grid = ggplot2::element_line(color = k[["line"]]),
    text = ggplot2::element_text(color = k[["text"]]),
    axis.text = ggplot2::element_text(color = k[["muted"]]))
}
